#include <iostream>
#include <vector>

int main() {
    int n;
    std::cin >> n;

    const long long MOD = 1000000007;
    int size = 2 * n + 1;
    std::vector<std::vector<long long>> dp(size, std::vector<long long>(size, 0));

    dp[1][1] = 1;

    for (int i = 2; i <= 2 * n; i++) {
        for (int j = 0; j <= i; j++) {
            if (j > 0) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;
            }
            if (j < 2 * n) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j + 1]) % MOD;
            }
        }
    }

    long long sum = 0;
    for (int i = 2 * n - 1; i >= 0; i -= 2) {
        for (int j = 0; j <= i; j++) {
            if (2 * n - i >= j) {
                sum = (sum + dp[i][j]) % MOD;
            }
        }
    }
    std::cout << sum << std::endl;
    return 0;
}
